// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address attacker) public {
        vm.assume(amount > 0 && amount <= 1000 ether);
        vm.assume(attacker != address(0) && attacker != address(c));

        // Deploy a re-entrant attacker that calls withdrawReward again in its receive
        ReentrantAttacker a = new ReentrantAttacker(c, address(this));

        // Fund the contract with enough ETH to cover both the initial reward and the re-entrant withdrawal
        vm.deal(address(c), amount * 2);
        // Also give the attacker some ETH for gas
        vm.deal(address(a), 1 ether);

        // As any user, give the attacker the first withdrawal bonus
        // This sets rewardsForA[attacker] = 100, then calls withdrawReward
        // The reference contract clears rewardsForA before the external call, so re-entrant withdrawReward sees 0
        // The buggy contract does NOT clear rewardsForA, so re-entrant withdrawReward sees 100 again and transfers another 100

        // We drive through getFirstWithdrawalBonus with the attacker address
        // The attacker contract's receive() will call back into withdrawReward
        c.getFirstWithdrawalBonus(address(a));

        // After the transaction, check the contract's ETH balance
        // If the contract allowed double spend (buggy), its balance will be less than expected
        // Expected: initial balance (amount*2) minus 100 (first withdrawal) = amount*2 - 100
        // Buggy: initial balance minus 200 (two withdrawals) = amount*2 - 200
        // The difference is 100 wei
        // A correct invariant: contract balance >= amount*2 - 100
        // The buggy version violates this for any amount where the contract has sufficient funds for two withdrawals
        assertTrue(address(c).balance >= amount * 2 - 100);
    }
}

contract ReentrantAttacker {
    C target;
    address testContract;
    bool hasReentered;

    constructor(C _target, address _testContract) {
        target = _target;
        testContract = _testContract;
    }

    receive() external payable {
        if (!hasReentered) {
            hasReentered = true;
            target.withdrawReward(address(this));
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));
        vm.assume(amount > 0);

        // Deploy a helper that can receive ETH but does not re-enter
        // The bug is about state cleanup, not re-entrancy, so a plain EOA-like receiver is fine.
        Receiver helper = new Receiver();
        address payable helperAddr = payable(address(helper));

        // Fund C so it can pay rewards
        vm.deal(address(c), amount + 100);

        // Manually set rewardsForA for the helper to simulate prior reward accrual
        // We need to give rewards to helper; we do this by calling getFirstWithdrawalBonus
        // which sets rewardsForA[helper] = 100, then withdraws. But that would reset claimedBonus.
        // Instead, we can directly set the storage slot? Not allowed.
        // We'll just use the public getFirstWithdrawalBonus which also tests withdrawReward.
        // But that would also set claimedBonus[helper] = true, preventing a second bonus.
        // For a pure withdrawReward test, we can't directly set rewardsForA without a setter.
        // So we'll use getFirstWithdrawalBonus on the helper, then observe state after.
        // This is acceptable since the rule should hold for any path that calls withdrawReward.

        // Record rewardsForA before the call by reading the public mapping (if it were public).
        // rewardsForA is private, so we cannot read it directly.
        // We must observe the state change indirectly.
        // After getFirstWithdrawalBonus, rewardsForA[helper] should be 0.
        // In the buggy version, it will still be 100.
        // We can call withdrawReward again with the helper, and if balance is enough, it might succeed.
        // But to assert, we need a public getter. None exists for rewardsForA.
        // We could make an assertion on the contract's balance or on subsequent behavior.
        // The rule: after withdrawReward, the reward mapping for that address is zeroed.
        // This can be observed by calling withdrawReward again: in the reference, it will transfer 0 (no change in balance),
        // but in the buggy, it will transfer again, reducing balance.
        // However, we cannot call withdrawReward directly on an address because it's _nonReentrant and we need to be the recipient?
        // withdrawReward is public and anyone can call it for any recipient.
        // So we can call withdrawReward(helper) twice from the same transaction or different.
        // But after the first call, the contract's balance will be reduced by 100.
        // In the buggy, the second call will attempt to transfer another 100.
        // We can assert that the contract's balance after two calls equals the expected amount.

        // Better: we can use a reverter helper to ensure the external call fails in the first attempt,
        // then observe that rewardsForA is still set. But we can't observe it directly.
        // Actually, we can make a helper that reverts on receive, so the transfer fails.
        // Then the require(success) will revert the transaction, leaving rewardsForA unchanged.
        // In the reference, rewardsForA is set to 0 before the call, so if the call reverts, the state is rolled back
        // and rewardsForA is restored to its original value (100). So no difference.
        // We need a scenario where the transaction succeeds, so we can compare states.

        // Let's use a receiving helper and check that the amount withdrawn is exactly what was in rewardsForA.
        // By checking the helper's balance increase, we can infer if rewardsForA was zeroed.
        // Since the bug is that rewardsForA is not zeroed, a second withdraw would give more.
        // That's a re-entrancy scenario, but the prompt says no re-entrancy needed? Actually the bug is missing zeroing,
        // which can be exploited by re-entrancy. But we can simply call withdrawReward twice in separate transactions.
        // After the first call, rewardsForA should be 0. If not zeroed, the second call will also transfer.
        // So we can assert that after two calls, the helper received exactly the initial reward.
        // But we need an initial reward. We'll use getFirstWithdrawalBonus to set the reward.

        // Step: call getFirstWithdrawalBonus(helper) which sets rewardsForA[helper] = 100 and calls withdrawReward.
        // This will succeed and transfer 100 to helper. In reference, rewardsForA[helper] becomes 0. In buggy, remains 100.
        // Then we call withdrawReward(helper) again. In reference, it will transfer 0 (no state change). In buggy, it will transfer another 100.
        // Assert that the helper's balance after two calls is exactly 100 (reference) or more (buggy).
        // Actually, in reference, second call transfers 0, so balance stays 100. In buggy, it transfers 100 again, so balance becomes 200.
        // So assert that helper balance == 100.

        // We need to fund c with enough ETH for two transfers. We already dealt.

        vm.startPrank(address(this));
        // Since getFirstWithdrawalBonus has no access control, anyone can call it.
        c.getFirstWithdrawalBonus(helperAddr);
        // Now call withdrawReward again
        c.withdrawReward(helperAddr);
        vm.stopPrank();

        uint256 helperBalance = helperAddr.balance;
        assertTrue(helperBalance == 100);
    }
}

