    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 ethAmount) public {
        // Bound to a reasonable amount that can be provided to the contract
        ethAmount = bound(ethAmount, 100, 1000 ether);
        // Deploy the reentrant attacker and give it the address of c
        Reenterer attacker = new Reenterer(address(c));
        // Fund c so it can pay rewards
        vm.deal(address(c), ethAmount);
        // The attacker calls getFirstWithdrawalBonus, which will trigger reentrancy
        vm.prank(address(attacker));
        bool topLevelReverted;
        try c.getFirstWithdrawalBonus(address(attacker)) {
            topLevelReverted = false;
        } catch {
            topLevelReverted = true;
        }
        // If the top-level call did not revert, claimedBonus must be true.
        // In the reference, the reentrant call sees rewardsForA cleared, so it gets 0 and succeeds;
        // top-level call finishes, setting claimedBonus to true.
        // In the buggy version, rewardsForA is not cleared, reentrant call drains extra ETH,
        // causing top-level to revert, leaving claimedBonus false.
        assertTrue(!topLevelReverted ? c.claimedBonus(address(attacker)) : true);
    }
}

contract Reenterer {
    C target;
    bool reentered;

    constructor(address _target) {
        target = C(_target);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.withdrawReward(address(this));
        }
    }

    // Exposed to allow prank calling from test
    function callGetFirstWithdrawalBonus() external {
        target.getFirstWithdrawalBonus(address(this));
    }
}

