import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(c) && recipient != address(0));
        vm.assume(recipient.code.length == 0); // keep it EOA to avoid reentrancy
        vm.deal(address(c), 1 ether);
        // Set rewardsForA[recipient] via getFirstWithdrawalBonus calling withdrawReward
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        c.getFirstWithdrawalBonus{value: 1 ether}(recipient);
        // Now read the public rewardsForA via the attacked getter (private variable has no public getter, so we cannot read it directly)
        // The only way to observe rewardsForA is through its effect on subsequent calls.
        // We'll make a second withdrawReward call (the same recipient) via another bonus request and observe revert/claimedBonus state.
        // But we need a public view into rewardsForA. Since rewardsForA is private and has no getter, we use balance changes.
        // Instead, we call getFirstWithdrawalBonus again with the same recipient and observe whether it reverts.
        // If rewardsForA is not zero, the bonus will add 100 and trigger withdrawReward for the full amount,
        // which may drain and revert. The reference clears rewardsForA, so second call succeeds.
        // The reference: after first getFirstWithdrawalBonus, rewardsForA[recipient] = 0.
        // In buggy, it's not zero, so second call adds 100, triggers withdrawReward for 100 more, possibly reverting if balance insufficient.
        // We can assert that the second getFirstWithdrawalBonus does NOT revert in reference, but reverts in buggy.
        bool secondCallOk;
        deal(address(this), 1 ether);
        vm.prank(address(this));
        try c.getFirstWithdrawalBonus(recipient) { secondCallOk = true; } catch { secondCallOk = false; }
        assertTrue(secondCallOk);
    }
}

