import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 feeAmount) public {
        vm.assume(recipient != address(0) && recipient != address(c) && recipient != address(this));
        vm.assume(feeAmount > 0);
        // send some ETH directly to c so there are funds to withdraw
        vm.deal(address(c), feeAmount);
        // record a reward for the recipient: call getFirstWithdrawalBonus
        vm.prank(address(this));
        c.getFirstWithdrawalBonus(recipient);
        // now withdrawReward
        (bool ok,) = address(c).call(abi.encodeWithSignature("withdrawReward(address)", recipient));
        // after the call, the recipient should have received the full reward that was cleared
        uint256 recipientBalance = address(recipient).balance;
        uint256 contractBalance = address(c).balance;
        // invariant: contract balance + recipient balance (initially 0) == initial contract balance + total rewards issued
        // simpler: after one getFirstWithdrawalBonus which adds 100, and a withdrawReward, the recipient must have received either 0 (if withdraw failed) or exactly 100 (if success)
        // the bug sends 1 instead of 100 => recipient balance != 100 if ok == true
        assertTrue(!ok || recipientBalance == 100);
    }
}

