        // Deploy a re-entrant attacker that triggers getFirstWithdrawalBonus during withdrawReward's external call
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), 1 ether);

        // Give attacker some rewards so withdrawReward sends Ether and calls back
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        // actor calls getFirstWithdrawalBonus, which adds rewards and calls withdrawReward -> external call to recipient
        // The recipient is the attacker contract, which re-enters getFirstWithdrawalBonus
        try c.getFirstWithdrawalBonus(address(attacker)) {
            // If no revert, reentrancy guard failed
            assertTrue(false, "Reentrancy succeeded but should have been blocked");
        } catch {
            // Revert expected, reentrancy guard works
            assertTrue(true);
        }
    }
}

contract ReentrantAttacker {
    C public target;
    bool private locked = false;

    constructor(C _target) {
        target = _target;
    }

    receive() external payable {
        if (!locked) {
            locked = true;
            // re-enter getFirstWithdrawalBonus which will try to call withdrawReward again
            // The _nonReentrant modifier should block this
            target.getFirstWithdrawalBonus(address(this));
            locked = false;
        }
    }
}

