import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 seed) public {
        // assume recipient is not the contract itself and not zero
        vm.assume(recipient != address(0) && recipient != address(c));
        // deploy a normal recipient that accepts ether so withdrawReward succeeds
        EmptyReceiver receiver = new EmptyReceiver();
        // make c think the deployed receiver has rewards and not yet claimed
        vm.deal(receiver, 1 ether);
        // we need to set up rewardsForA for the recipient and claimedBonus false
        // those are internal mappings with no direct setter, so we use getFirstWithdrawalBonus
        // but that requires a call that itself uses the modifier. Instead, we can observe _locked after any success.
        // Any successful call through _nonReentrant must leave _locked false. We'll call getFirstWithdrawalBonus with the empty receiver
        // which will call withdrawReward and then set claimedBonus. Since the receiver accepts ether, the call succeeds.
        vm.assume(seed != 0);
        // give some balance to the contract to pay rewards
        vm.deal(address(c), 100 ether);
        // prank the call from the receiver address (it must have no claimedBonus)
        vm.prank(address(receiver));
        // getFirstWithdrawalBonus internally calls withdrawReward and should unlock
        c.getFirstWithdrawalBonus(address(receiver));
        // after a successful call through the modifier, _locked must be false
        assertTrue(!c._locked());
    }
}

