pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));

        // Fund the contract so it can pay the bonus
        vm.deal(address(c), 200 ether);

        // First call should succeed
        vm.prank(recipient);
        c.getFirstWithdrawalBonus(recipient);

        // After first claim, claimedBonus[recipient] must be true and rewards should be 0.
        // The general rule: after a successful claim via the intended entry point,
        // claimedBonus is true and the bonus has been withdrawn (rewardsForA == 0).
        // The bug removes the require(!claimedBonus), allowing a second claim that
        // will set rewardsForA[recipient] to 100 then withdraw, leaving rewardsForA[recipient] == 0
        // but still not reverting. We check that after a second attempt (which the reference
        // would revert on) the state remains consistent with the rule.

        bool secondAttemptReverted;
        vm.prank(recipient);
        try c.getFirstWithdrawalBonus(recipient) {
            secondAttemptReverted = false;
        } catch {
            secondAttemptReverted = true;
        }

        // If the second attempt reverted (reference behaviour), claimedBonus should still be true
        // and rewardsForA should still be 0. If it didn't revert (bug), then after the call
        // rewardsForA must be 0 (withdrawn again) and claimedBonus still true.
        // In both cases, claimedBonus must be true, which is the invariant the reference maintains
        // (once claimed, always true). The bug violates this because the require that enforces
        // once-only claim is missing, but we need to capture the actual difference.
        // The difference is that the reference reverts on the second call (so Ether balance of C
        // decreases by exactly 100), while the bug allows draining more. The simplest observable
        // invariant that holds for the reference and fails for the bug:
        // After two calls (first always succeeds, second may revert), the contract ETH balance
        // is exactly initialBalance - 100 (reference) or lower (bug).

        // Simpler: after the first successful call, claimedBonus[recipient] is true.
        // The reference will always revert on a second call, so claimedBonus remains true.
